import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { lightNormalizeCode } from '../src/standards-db/light-normalize.js';

/**
 * Shared-fixture parity: this fixture is generated by elib (the source
 * of truth for normalized_code) and copied verbatim into this repo.
 * Reverse_proxy's lightNormalizeCode is a copy of elib's function and
 * must agree on every case — this test is what keeps the two repos'
 * merge keys identical.
 */

interface FixtureCase {
  input: string;
  year_field: number | null;
  normalized_code: string | null;
  base_key: string | null;
  code_key_raw: string | null;
  year: number | null;
  amendment_year: number | null;
  is_amendment: boolean;
  is_draft: boolean;
  needs_review: boolean;
  skipped_reason: string | null;
}

const cases = JSON.parse(
  readFileSync(new URL('./fixtures/code-normalize-shared.json', import.meta.url), 'utf8')
) as FixtureCase[];

describe('lightNormalizeCode — shared fixture parity with elib', () => {
  it('fixture has the expected breadth (86 cases)', () => {
    expect(cases.length).toBe(86);
  });

  it.each(cases.map((c, i) => [i, c] as const))('case %i matches elib output', (_i, expected) => {
    const actual = lightNormalizeCode(expected.input, expected.year_field);
    if (expected.normalized_code === null && expected.skipped_reason === null) {
      // elib's function returned null (not a code at all).
      expect(actual).toBeNull();
      return;
    }
    expect(actual).not.toBeNull();
    expect({
      normalized_code: actual?.normalized_code,
      base_key: actual?.base_key,
      code_key_raw: actual?.code_key_raw,
      year: actual?.year,
      amendment_year: actual?.amendment_year,
      is_amendment: actual?.is_amendment,
      is_draft: actual?.is_draft,
      needs_review: actual?.needs_review,
      skipped_reason: actual?.skipped_reason
    }).toEqual({
      normalized_code: expected.normalized_code,
      base_key: expected.base_key,
      code_key_raw: expected.code_key_raw,
      year: expected.year,
      amendment_year: expected.amendment_year,
      is_amendment: expected.is_amendment,
      is_draft: expected.is_draft,
      needs_review: expected.needs_review,
      skipped_reason: expected.skipped_reason
    });
  });
});
